	"svelte",
	"rs",
	"json",
	"toml",
	"yaml",
	"yml",
	"txt",
	"html",
	"css",
	"vue",
	"py",
	"go",
	"lock",
	"png",
	"jpg",
	"svg",
	"sh",
	"tsx",
	"jsx",
	"mjs",
	"cjs",
	"log",
]);

