import { describe, expect, test } from "bun:test";
import { taskTitle } from "../apps/client/src/lib/projects/terminal-title.ts";

describe("taskTitle", () => {
	test("claude: topic without the spinner glyph", () => {
		expect(taskTitle("claude", "✳ Terminal blind overlay")).toBe("Terminal blind overlay");
		expect(taskTitle("claude", "⠂ Terminal blind overlay")).toBe("Terminal blind overlay");
		expect(taskTitle("claude", "✳ Claude Code")).toBeNull();
		expect(taskTitle("claude", "")).toBeNull();
	});
	test("pi: the session name between the app title and the folder", () => {
		expect(taskTitle("pi", "π - fix login - dashboard")).toBe("fix login");
		expect(taskTitle("pi", "Pi-Bolt - a - b - dashboard")).toBe("a - b");
		expect(taskTitle("pi", "π - dashboard")).toBeNull();
	});
});

/** Shift+Enter 가 셸·TUI 에 보내는 바이트. 일반 Enter 와 같은 `\r` 이 가면 Claude Code 같은 입력기는 줄바꿈이 아니라
 *  제출로 읽는다. ESC+CR(Alt+Enter)은 셸에서 무해하고 TUI 입력기에서 줄바꿈이다(Orca terminal-shortcut-policy). */
export const SHIFT_ENTER_INPUT = "\x1b\r";

/** xterm modifyOtherKeys 형식의 Shift+Enter: `CSI 27 ; 2 ; 13 ~`. */
const SHIFT_ENTER_MODIFY_OTHER_KEYS = "\x1b[27;2;13~";

/** modifyOtherKeys 를 켠 앱이 Shift+Enter 로 받길 기대하는 바이트. pi 는 kitty 키보드 프로토콜 질의에 답이 없으면
 *  `CSI > 4 ; 2 m` 으로 내려가는데, 그 모드에서 ESC+CR 은 Alt+Enter(후속 메시지 제출)라 줄바꿈이 되지 않는다. 레벨 1 은
 *  Enter 를 바꾸지 않으므로(fish 가 입력 중에 켠다) 2 부터다. 켠 앱이 없으면 ESC+CR 이다. */
export function shiftEnterInput(modifyOtherKeys: number): string {
	return modifyOtherKeys >= 2 ? SHIFT_ENTER_MODIFY_OTHER_KEYS : SHIFT_ENTER_INPUT;
}

/** `CSI > Pp ; Pv m` 의 인자에서 modifyOtherKeys 레벨. `Pp` 가 4 가 아니면 다른 자원이라 `null`, `Pv` 를 생략하면
 *  기본값(끔)으로 되돌리는 것이므로 0 이다. */
export function modifyOtherKeysLevel(params: readonly (number | number[])[]): number | null {
	if (params[0] !== 4) return null;
	const level = params[1];
	return typeof level === "number" && level > 0 ? level : 0;
}

type KeyLike = Pick<KeyboardEvent, "key" | "shiftKey" | "ctrlKey" | "altKey" | "metaKey" | "isComposing">;

/** 맨 Shift+Enter 인가. IME 조합 중에는 조합 확정 키이므로 제외한다. */
export function isShiftEnter(event: KeyLike): boolean {
	return (
		event.key === "Enter" && event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey && !event.isComposing
	);
}
===
/**
 * 하네스 = 명령을 실제로 돌리는 CLI. 모델 목록과 effort 목록은 하네스가 정한다.
 *
 * - `pi`: 서버가 Pi 설정에서 읽어 주는 카탈로그(`GET /api/pi/models`). 로그인된 provider만.
 * - `claude`: Claude Code CLI(`claude -p --model {id} --effort {level}`). 모델은 서버가 Anthropic에서
 *   읽어 주는 카탈로그(`GET /api/claude/models`)이고, 인증은 `~/.claude/.credentials.json` 한 곳이다
 *   (`.agents/rules/providers.md`).
 *
 * 기획: `docs/plan/260928-worktree-workflow.md` §1.
 */
import { claudeCatalog } from "$lib/projects/claude-models.svelte.js";
import {
	clampPiEffort,
	piEffortsFor,
	piPickerItems,
	type PiEffort,
	type PiPickerItem,
	type PiProvider,
	withCurrentModel,
} from "$lib/projects/pi-models.js";

export type Harness = "pi" | "claude";
export const HARNESSES: Harness[] = ["pi", "claude"];

/** 역할 하나의 선택. Worker는 worktree 작업, Lead는 검토와 plain 명령. */
