/**
 * 터미널이 OSC 0/2 로 보내는 제목에서 `지금 하는 일` 만 뽑는다.
 *
 * - pi: `π - {세션 이름} - {폴더}` 또는 세션이 없으면 `π - {폴더}`. 앱 이름(`APP_TITLE`)은 `π` · `Pi-Bolt` ·
 *   사용자 설정 이름이라 첫 마디를 그대로 건너뛴다. 마지막 마디는 cwd 폴더이고, 가운데가 세션 이름이다.
 * - claude: `{스피너} {대화 제목}`. 제목이 없으면(아무 작업도 안 할 때) `Claude Code` 다.
 *
 * 두 하네스 모두 앞에 스피너 글리프를 붙인다(pi 의 titlebar-spinner 확장은 점자 프레임, Claude Code 는 ✳·✻··).
 * 순수 함수만 있고 저장소도 브라우저도 모른다: 무엇을 보여 줄지는 부르는 쪽이 정한다.
 */

/** 제목 앞의 스피너 글리프: 점자(U+2800–U+28FF)와 Claude Code 가 쓰는 별·가운뎃점 계열. */
const SPINNER = /^[\u2800-\u28ff\u00b7\u2022\u2217*\u2733\u2736\u2739\u273b\u273d\u273f\u2740\u2742]+\s*/u;

/** Claude Code 가 할 일이 없을 때 두는 기본 제목. */
const CLAUDE_IDLE = new Set(["Claude Code", "Claude"]);

/** 제목의 구분자. 앱 이름 · 세션 이름 · 폴더를 가른다. */
const SEPARATOR = " - ";

/** 하네스의 원시 제목에서 작업 이름만. 스피너뿐이거나 기본 제목이면 `null`(탭은 자기 이름을 그대로 쓴다). */
export function taskTitle(harness: string, title: string | null | undefined): string | null {
	const text = (title ?? "").replace(SPINNER, "").trim();
	if (!text) return null;
	if (harness === "claude") return CLAUDE_IDLE.has(text) ? null : text;
	return piSessionTitle(text);
}

/** `π - {세션} - {폴더}` 에서 세션 이름. 세션이 없거나(`π - {폴더}`) 비어 있으면 `null`. */
function piSessionTitle(title: string): string | null {
	const parts = title.split(SEPARATOR);
	/* 앱 이름과 폴더, 두 마디뿐이면 세션 이름이 없다. 세션 이름 자체가 ` - ` 를 품을 수 있어 가운데를 다시 잇는다. */
	if (parts.length < 3) return null;
	const name = parts.slice(1, -1).join(SEPARATOR).trim();
	return name || null;
}
